mapper.select:
SELECT COALESCE(SUM(CASE WHEN t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to}
THEN 1 ELSE 0 END), 0) AS doneCount, COALESCE(SUM(CASE WHEN t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to} AND t.due_at IS NOT NULL
THEN 1 ELSE 0 END), 0) AS doneWithDueCount, COALESCE(SUM(CASE WHEN t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to} AND t.due_at IS NOT NULL AND t.done_at <= t.due_at
THEN 1 ELSE 0 END), 0) AS onTimeCount, COALESCE(SUM(CASE WHEN t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to} AND t.due_at IS NULL
THEN 1 ELSE 0 END), 0) AS doneNoDueCount, COALESCE(SUM(CASE WHEN t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to} AND t.due_at IS NOT NULL AND t.done_at > t.due_at
THEN 1 ELSE 0 END), 0) AS lateDoneCount, COALESCE(SUM(CASE WHEN t.status = 'OPEN'
THEN 1 ELSE 0 END), 0) AS openCount, COALESCE(SUM(CASE WHEN t.status = 'OPEN' AND t.due_at IS NOT NULL AND t.due_at < #{now}
THEN 1 ELSE 0 END), 0) AS overdueOpenCount, COALESCE(SUM(CASE WHEN t.status IN ('CANCELLED', 'EXPIRED') AND t.done_at >= #{from} AND t.done_at < #{to}
THEN 1 ELSE 0 END), 0) AS cancelledOrExpiredCount FROM workspace_task t WHERE t.org_id = #{orgId} AND t.is_deleted = 0 AND ( t.status = 'OPEN' OR (t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to}) OR (t.status IN ('CANCELLED', 'EXPIRED') AND t.done_at >= #{from} AND t.done_at < #{to}) )

SELECT AS staffId, MAX(sp.display_name) AS staffName, COUNT(1) AS doneCount, SUM(CASE WHEN t.due_at IS NOT NULL THEN 1 ELSE 0 END) AS doneWithDueCount, SUM(CASE WHEN t.due_at IS NOT NULL AND t.done_at <= t.due_at THEN 1 ELSE 0 END) AS onTimeCount, 0 AS overdueOpenCount, 0 AS followupDoneCount FROM workspace_task t LEFT JOIN staff_profile sp ON sp.id = AND sp.is_deleted = 0 WHERE t.org_id = #{orgId} AND t.is_deleted = 0 AND t.status = 'DONE' AND t.done_at >= #{from} AND t.done_at < #{to} AND IS NOT NULL
AND IN ()
GROUP BY ORDER BY doneCount DESC, staffId ASC LIMIT #{limit}

SELECT COUNT(1)
FROM followup_record f
WHERE f.org_id = #{orgId}
  AND f.is_deleted = 0
  AND f.status = 'DONE'
  AND f.completed_at >= #{from}
  AND f.completed_at < #{to}

      AND f.completed_by_staff_id IN (
          SELECT ctm.staff_id FROM care_team_member ctm
          WHERE ctm.team_id = #{careTeamId}
            AND ctm.member_type = 'STAFF'
            AND ctm.is_deleted = 0
            AND ctm.staff_id IS NOT NULL
      )


      AND f.completed_by_staff_id = #{staffId}

SELECT COUNT(1) FROM followup_record f WHERE f.org_id = #{orgId} AND f.is_deleted = 0 AND f.source = 'PATIENT_REQUEST' AND ( (f.status = 'DONE' AND f.completed_at >= #{from} AND f.completed_at < #{to}) OR (f.status = 'OPEN' AND f.gmt_created >= #{from} AND f.gmt_created < #{to}) )
AND COALESCE(f.completed_by_staff_id, f.assignee_staff_id) IN ( SELECT ctm.staff_id FROM care_team_member ctm WHERE ctm.team_id = #{careTeamId} AND ctm.member_type = 'STAFF' AND ctm.is_deleted = 0 AND ctm.staff_id IS NOT NULL )
AND COALESCE(f.completed_by_staff_id, f.assignee_staff_id) = #{staffId}

SELECT COUNT(1)
FROM health_report r
WHERE r.org_id = #{orgId}
  AND r.is_deleted = 0
  AND r.status = 'PUBLISHED'
  AND r.published_at >= #{from}
  AND r.published_at < #{to}

      AND r.published_by_staff_id IN (
          SELECT ctm.staff_id FROM care_team_member ctm
          WHERE ctm.team_id = #{careTeamId}
            AND ctm.member_type = 'STAFF'
            AND ctm.is_deleted = 0
            AND ctm.staff_id IS NOT NULL
      )


      AND r.published_by_staff_id = #{staffId}

SELECT DISTINCT ctm.team_id
FROM care_team_member ctm
WHERE ctm.org_id = #{orgId}
  AND ctm.staff_id = #{staffId}
  AND ctm.member_type = 'STAFF'
  AND ctm.is_deleted = 0
